#!/usr/bin/env python3
from pwn import *

def test_input(input_str):
    print(f"Testing input: '{input_str}'")
    p = process(['./main'])
    p.sendlineafter(b'Enter your path:', input_str.encode())
    output = p.recv(timeout=1)
    if not output:
        try:
            p.proc.kill()
        except:
            pass
        return "No output received"
    return output.decode(errors='ignore')

inputs = [
    "U", "D", "R", "L",
    "UR", "UL", "DR", "DL",
    "UDRL", "URDL", 
    "UUUU", "RRRR", "DDDD", "LLLL",
    "URDLURDLURDL"
]

for input_str in inputs:
    result = test_input(input_str)
    print(f"Result: {result}")
    print("-" * 50)

